-- 008-product-barcode.sql  (Bren, POS: changes POS's own products table)
-- Panel feedback (Nov 11): barcode generator. A product can have its own registered barcode
-- (a manufacturer's barcode scanned from the package, or one generated by POS). Products without one
-- still scan by product_code (PRD-0001). New nullable column: nothing existing changes, other modules don't read it.
-- Same as pos/sql/optional-barcode.sql. Run once on the DB host (and on solo-mode laptops).
USE mindafresh_db;

ALTER TABLE products
  ADD COLUMN barcode VARCHAR(50) NULL AFTER product_code,
  ADD UNIQUE KEY uq_products_barcode (barcode);
